function load(){try{const s=JSON.parse(localStorage.getItem('teztaom-seller-v1'));if(backupValid(s)){const demoOwner=s.staff.find(x=>x.id==='s1'&&['Sherzod Raxmonov','Restoran egasi'].includes(x.name));if(demoOwner)demoOwner.name='Norpulatov Abdumajid';if(s.brandRevision!==1){s.profile.name='lazzat.uz';s.profile.phone='+998 99 069 18 51';const owner=s.staff.find(x=>x.id==='s1');if(owner&&owner.phone==='+998 90 123 45 67')owner.phone='+998 99 069 18 51';s.brandRevision=1;}if(s.logoRevision!==1){s.profile.logo='assets/lazzat-logo.png';s.logoRevision=1;}return s;}}catch{}return seed();}
let state=load(), page='orders', orderTab='active', menuTab='all', search='', reviewFilter='all', financePeriod='all', analyticsPeriod=7, modalReturn=null, audioContext;
function save(){try{localStorage.setItem('teztaom-seller-v1',JSON.stringify(state));return true;}catch{storageWarning=true;toast('Saqlash joyi yetarli emas. Kichikroq rasm yuklang yoki ma’lumotlarni eksport qiling.');return false;}}
function commit(next){const previous=state;state=next;if(!save()){state=previous;return false;}return true;}
function update(fn){const next=structuredClone(state);fn(next);return commit(next);}
let toastTimeout;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function btn(text,action,id='',cls='',ico=''){const label=({print:'Chek chiqarish',product:'Mahsulotni tahrirlash','delete-product':'Mahsulotni o‘chirish','delete-promo':'Aksiyani o‘chirish','delete-category':'Kategoriyani o‘chirish',branch:'Filialni tahrirlash',staff:'Xodimni tahrirlash'})[action]||'Amal';return `<button type="button" class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} ${!text?`aria-label="${label}" title="${label}"`:''}>${ico?icon(ico):''}${text}</button>`;}
const total = o => o.items.reduce((s,i)=>s+i.price*i.qty,0);
const inBranch = o => state.selectedBranch==='all'||o.branch===state.selectedBranch;
const orders = () => state.orders.filter(inBranch);
