const statusTag = s => `<span class="tag ${s==='completed'||s==='ready'?'success':s==='rejected'?'danger':s==='preparing'?'warning':''}">${statusLabel[s]}</span>`;
const image = p => p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:esc(p.emoji||'🍽️');
function header(title,subtitle,actions=''){return `<div class="page-title"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,unit,note,ico])=>`<article class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><strong>${value} ${unit?`<small>${unit}</small>`:''}</strong><div class="stat-bottom">${note}</div></article>`).join('')}</div>`;}
function empty(text){return `<div class="empty">${icon('bag')}${text}</div>`;}
