function renderSchedule(){
 const branch=state.branches.find(b=>b.id===state.selectedBranch)||state.branches[0];
 return header('Ish vaqti','Filiallar jadvali va buyurtmalar qabul qilish rejimi.',btn('Filial qo‘shish','branch','','primary','plus'))+`<div class="two-col"><div class="panel"><div class="panel-head"><h2>Haftalik ish jadvali</h2><select class="btn" id="schedule-branch" aria-label="Jadval uchun filial">${state.branches.map(b=>`<option value="${esc(b.id)}" ${branch.id===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><form id="schedule-form" data-id="${esc(branch.id)}"><div class="schedule-row muted" style="font-size:9px"><span>HAFTA KUNI</span><span>OCHILISH</span><span>YOPILISH</span></div>${branch.schedule.map((d,i)=>`<div class="schedule-row"><label><input type="checkbox" name="open${i}" ${d.open?'checked':''}> ${esc(d.name)}</label><input type="time" name="from${i}" value="${d.from}" aria-label="${esc(d.name)} ochilish vaqti" required><input type="time" name="to${i}" value="${d.to}" aria-label="${esc(d.name)} yopilish vaqti" required></div>`).join('')}<p class="subtitle" style="margin-top:15px">Belgi olib tashlangan kunlar dam olish kuni hisoblanadi. Tun oshadigan jadval qo‘llanadi (masalan, 18:00–02:00).</p><div class="dialog-footer"><button class="btn primary" type="submit">${icon('check')}Jadvalni saqlash</button></div></form></div><div><div class="panel"><div class="panel-head"><h2>Buyurtma qabul qilish</h2><span class="tag ${state.busy?'warning':'success'}">${state.busy?'Band':'Ochiq'}</span></div><p class="subtitle">Oshxona band bo‘lsa, yangi buyurtmalarni vaqtincha to‘xtating. Bu sozlama barcha filiallarga tegishli.</p><div style="margin-top:20px">${btn(state.busy?'Qabul qilishni yoqish':'Band rejimini yoqish','busy','','soft','clock')}</div></div><div class="panel"><h2>Filiallar</h2>${state.branches.map(b=>`<div class="branch"><span class="stat-icon">${icon('pin')}</span><div><strong>${esc(b.name)}</strong><p>${esc(b.address)}</p><span class="tag ${b.active?'success':'warning'}">${b.active?'Faol':'Yopiq'}</span></div><div class="actions">${btn('','branch',b.id,'small','edit')}${btn(b.active?'Yopish':'Ochish','branch-active',b.id,'small')}</div></div>`).join('')}</div></div></div>`;
}
function promoActive(p){return p.active&&new Date(p.ends+'T23:59:59')>=new Date();}
function renderPromos(){return header('Aksiyalar','Mazali takliflar bilan savdoni oshiring.',btn('Aksiya yaratish','promotion','','primary','plus'))+`<div class="info-strip">${icon('promo')}Aksiyalar demo ma’lumotlar sifatida saqlanadi. Chegirmalarni mijoz buyurtmalariga qo‘llash server ulangandan keyin ishlaydi.</div><div class="three-col">${state.promos.map(p=>`<article class="panel promo-card"><span class="tag ${promoActive(p)?'success':'warning'}">${promoActive(p)?'● Faol':p.active?'Muddati tugagan':'To‘xtatilgan'}</span><strong>${p.type==='combo'?money(p.value)+' so‘m':p.value+'% chegirma'}</strong><h2>${esc(p.name)}</h2><p>${p.type==='promo'?`Promokod: <b>${esc(p.code)}</b>`:p.type==='combo'?`${p.products?.map(id=>esc(state.products.find(x=>x.id===id)?.name||'O‘chirilgan mahsulot')).join(' + ')}`:'Barcha taomlar uchun chegirma'}<br>Minimal buyurtma: ${money(p.minOrder)} so‘m<br>Amal qiladi: ${esc(p.ends)}</p><div class="actions">${btn('Tahrirlash','promotion',p.id,'small','edit')}${btn(p.active?'To‘xtatish':'Yoqish','promo-active',p.id,'small')}${btn('','delete-promo',p.id,'small','trash')}</div></article>`).join('')}</div>${!state.promos.length?empty('Hozircha aksiyalar yo‘q'):''}`;}
function financials(list){const completed=list.filter(o=>o.status==='completed');const sales=completed.reduce((s,o)=>s+total(o),0);const commission=completed.reduce((s,o)=>s+Math.round(total(o)*state.profile.commission/100),0);return {sales,commission,net:sales-commission,count:completed.length};}
function renderFinance(){
 const list=orders().filter(o=>financePeriod==='all'||new Date(o.completed||o.created).toDateString()===new Date().toDateString()),f=financials(list),paid=state.payouts.reduce((s,p)=>s+p.amount,0);
 return header('Moliya','Savdo, komissiya va to‘lovlar bo‘yicha aniq hisob.',btn('Hisobotni yuklash','export-finance','','primary','download'))+`<div class="info-strip">${icon('wallet')}Hisoblar yetkazilgan demo buyurtmalardan olinadi. Haqiqiy pul yechish va to‘lov tizimi ulanmagan.</div>`+stats([['Jami savdo',money(f.sales),'so‘m',`${f.count} ta yakunlangan buyurtma`,'wallet'],['Platforma komissiyasi',money(f.commission),'so‘m',`${state.profile.commission}% — demo hisoblash stavkasi`,'promo'],['Sof tushum',money(f.net),'so‘m','Savdo − platforma komissiyasi','chart'],['To‘lovlar tarixi',money(paid),'so‘m',`${state.payouts.length} ta amalga oshirilgan to‘lov`,'check']])+`<div class="panel"><div class="panel-head"><h2>Savdo operatsiyalari</h2><select id="finance-period" class="btn" aria-label="Hisobot davri"><option value="all" ${financePeriod==='all'?'selected':''}>Barcha vaqt</option><option value="today" ${financePeriod==='today'?'selected':''}>Bugun</option></select></div><div class="table-wrap"><table><thead><tr><th>BUYURTMA</th><th>SANA</th><th>SAVDO</th><th>KOMISSIYA</th><th>SOF TUSHUM</th><th>TO‘LOV USULI</th></tr></thead><tbody>${list.filter(o=>o.status==='completed').map(o=>`<tr><td><strong>#${esc(o.id)}</strong></td><td>${new Date(o.completed||o.created).toLocaleString('uz-UZ')}</td><td>${money(total(o))}</td><td>${money(Math.round(total(o)*state.profile.commission/100))}</td><td><strong>${money(total(o)-Math.round(total(o)*state.profile.commission/100))}</strong></td><td>${esc(o.payment)}</td></tr>`).join('')}</tbody></table>${!f.count?empty('Tanlangan davrda yakunlangan savdolar yo‘q'):''}</div></div><div class="panel"><h2>To‘lovlar tarixi</h2>${state.payouts.length?`<div class="table-wrap"><table><thead><tr><th>SANA</th><th>SUMMA</th><th>HOLAT</th></tr></thead><tbody>${state.payouts.map(p=>`<tr><td>${esc(p.date)}</td><td>${money(p.amount)} so‘m</td><td><span class="tag success">To‘landi</span></td></tr>`).join('')}</tbody></table></div>`:empty('Hali to‘lovlar yo‘q. Haqiqiy hisob-kitoblar to‘lov tizimi ulangach ko‘rinadi.')}</div>`;
}
function renderAnalytics(){
 const days=Array.from({length:analyticsPeriod},(_,i)=>{const d=new Date();d.setDate(d.getDate()-analyticsPeriod+1+i);return {date:d,label:d.toLocaleDateString('uz-UZ',{day:'numeric',month:'short'}),sales:0,count:0};});
 const completed=orders().filter(o=>o.status==='completed'&&days.some(d=>new Date(o.completed||o.created).toDateString()===d.date.toDateString()));
 completed.forEach(o=>{const d=days.find(d=>new Date(o.completed||o.created).toDateString()===d.date.toDateString());d.sales+=total(o);d.count++;});
 const f=financials(completed),max=Math.max(...days.map(d=>d.sales),1),top={};completed.forEach(o=>o.items.forEach(i=>{top[i.name]??={qty:0,sales:0};top[i.name].qty+=i.qty;top[i.name].sales+=i.qty*i.price;}));const ranks=Object.entries(top).sort((a,b)=>b[1].sales-a[1].sales),hours=Array.from({length:12},(_,i)=>completed.filter(o=>Math.floor(new Date(o.created).getHours()/2)===i).length),peak=Math.max(...hours);
 return header('Analitika','Savdo ko‘rsatkichlaringizni kuzating va o‘sish nuqtalarini toping.',`<select id="analytics-period" class="btn" aria-label="Analitika davri"><option value="7" ${analyticsPeriod===7?'selected':''}>Oxirgi 7 kun</option><option value="14" ${analyticsPeriod===14?'selected':''}>Oxirgi 14 kun</option></select>`)+stats([['Jami savdo',money(f.sales),'so‘m',`Oxirgi ${analyticsPeriod} kun`,'wallet'],['Yakunlangan buyurtmalar',f.count,'ta','Tanlangan davr uchun','bag'],['O‘rtacha chek',money(f.count?Math.round(f.sales/f.count):0),'so‘m','Savdo / buyurtmalar soni','chart'],['Eng gavjum vaqt',peak?`${hours.indexOf(peak)*2}:00`:'—','',peak?`${peak} ta buyurtma, 2 soatlik oraliq`:'Hozircha ma’lumot yo‘q','clock']])+`<div class="two-col"><div class="panel"><div class="panel-head"><h2>Savdo dinamikasi</h2><span class="tag">so‘m</span></div><p class="subtitle">Faqat yakunlangan buyurtmalar hisoblanadi.</p><div class="chart" role="img" aria-label="Kunlik savdo diagrammasi">${days.map(d=>`<div class="bar-wrap" title="${esc(d.label)}: ${money(d.sales)} so‘m"><span class="bar-value">${d.sales?money(d.sales):'0'}</span><div class="bar" style="height:${Math.max(2,d.sales/max*80)}%"></div><small>${esc(d.label)}</small></div>`).join('')}</div></div><div class="panel"><h2>Top mahsulotlar</h2>${ranks.slice(0,5).map(([name,v],i)=>`<div class="rank"><span>0${i+1}</span><div class="product-pic">${image(state.products.find(p=>p.name===name)||{name,emoji:'🍽️'})}</div><div><strong>${esc(name)}</strong><small>${v.qty} ta sotilgan</small></div><b>${money(v.sales)}</b></div>`).join('')||empty('Yakunlangan buyurtmalar yo‘q')}</div></div><div class="panel"><div class="panel-head"><h2>Gavjum soatlar</h2><span class="subtitle">Buyurtma yaratilgan vaqt bo‘yicha</span></div><div class="heatmap">${hours.map((n,i)=>`<div class="heat-cell ${n&&n===peak?'hot':''}" style="${n&&n!==peak?'background:#cdb2f4':''}" title="${i*2}:00–${i*2+2}:00: ${n} ta buyurtma">${n} ta</div>`).join('')}</div><div class="heat-labels">${hours.map((_,i)=>`<span>${String(i*2).padStart(2,'0')}:00</span>`).join('')}</div></div>`;
}
function renderReviews(){const average=state.reviews.length?(state.reviews.reduce((s,r)=>s+r.rating,0)/state.reviews.length).toFixed(1):'—';const list=state.reviews.filter(r=>reviewFilter==='all'||reviewFilter==='unanswered'&&!r.reply||reviewFilter==='low'&&r.rating<=3);return header('Sharhlar','Mijoz fikrlari — yaxshiroq xizmat sari bir qadam.')+stats([['O‘rtacha baho',average,'/ 5','Mijozlarning umumiy bahosi','star'],['Jami sharhlar',state.reviews.length,'ta','Barcha mijoz fikrlari','orders'],['Javob kutilmoqda',state.reviews.filter(r=>!r.reply).length,'ta','Javob yozilmagan sharhlar','clock'],['Shikoyatlar',state.reviews.filter(r=>r.reported).length,'ta','Ko‘rib chiqish uchun belgilangan','help']])+`<div class="two-col"><div class="panel"><div class="panel-head"><h2>Mijozlar fikri</h2><select class="btn" id="review-filter" aria-label="Sharhlarni filtrlash"><option value="all" ${reviewFilter==='all'?'selected':''}>Barchasi</option><option value="unanswered" ${reviewFilter==='unanswered'?'selected':''}>Javobsiz</option><option value="low" ${reviewFilter==='low'?'selected':''}>3 va past baholar</option></select></div>${list.map(r=>`<article class="review"><div class="review-top"><div class="avatar">${esc(r.name.charAt(0))}</div><div><strong>${esc(r.name)}</strong><small>#${esc(r.order)} • ${esc(r.date)}</small></div><div class="stars" aria-label="${r.rating} yulduz">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div></div><p>${esc(r.text)}</p>${r.reply?`<div class="reply"><strong>Restoran javobi</strong>${esc(r.reply)}</div>`:''}<div class="actions">${btn(r.reply?'Javobni tahrirlash':'Javob yozish','reply',r.id,'small soft','edit')}${r.reported?'<span class="tag warning">Shikoyat belgilangan</span>':btn('Shikoyat qilish','report-review',r.id,'small')}</div></article>`).join('')||empty('Sharhlar topilmadi')}</div><div class="panel" style="align-self:start"><h2>Baholar taqsimoti</h2>${[5,4,3,2,1].map(n=>{const count=state.reviews.filter(r=>r.rating===n).length;return `<div class="summary-line"><span class="stars">${n} ★</span><strong>${count} ta</strong></div><div class="progress-track"><i style="width:${state.reviews.length?count/state.reviews.length*100:0}%"></i></div>`;}).join('')}<p class="subtitle" style="margin-top:25px">Shikoyatlar shu brauzerda belgilanadi. Moderatorga yuborish server integratsiyasini talab qiladi.</p></div></div>`;}
function renderStaff(){return header('Xodimlar','Jamoangiz uchun rollar va bo‘lim ruxsatlarini boshqaring.',btn('Xodim qo‘shish','staff','','primary','plus'))+`<div class="info-strip">${icon('users')}Bu yerda rollar va ruxsatlar konfiguratsiyasi saqlanadi. Haqiqiy kirish, autentifikatsiya va serverdagi ruxsat nazorati hali ulanmagan.</div><div class="panel table-wrap"><table><thead><tr><th>XODIM</th><th>TELEFON</th><th>ROL</th><th>RUXSATLAR</th><th>HOLAT</th><th>AMALLAR</th></tr></thead><tbody>${state.staff.map(s=>`<tr><td><div class="product-name"><div class="avatar">${esc(s.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><strong>${esc(s.name)}</strong></div></td><td>${esc(s.phone)}</td><td><span class="tag">${esc(s.role)}</span></td><td title="${esc(s.permissions.map(id=>navItems.find(n=>n[0]===id)?.[1]).join(', '))}">${s.permissions.length} ta bo‘lim</td><td><span class="tag ${s.active?'success':'warning'}">${s.active?'Faol':'O‘chirilgan'}</span></td><td>${s.role==='Ega'?'<span class="muted">Asosiy hisob</span>':`<div class="actions">${btn('','staff',s.id,'small','edit')}${btn(s.active?'O‘chirish':'Yoqish','staff-active',s.id,'small')}</div>`}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>Standart rollar</h2><div class="table-wrap"><table><thead><tr><th>ROL</th><th>STANDART RUXSATLAR</th></tr></thead><tbody>${Object.entries(roles).map(([role,ids])=>`<tr><td><strong>${role}</strong></td><td>${ids.map(id=>navItems.find(n=>n[0]===id)[1]).join(', ')}</td></tr>`).join('')}</tbody></table></div></div>`;}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function renderSettings(){const p=state.profile;return header('Sozlamalar','Restoran ma’lumotlari va panel sozlamalari.')+`<form id="settings-form"><div class="two-col"><div class="panel"><h2>Restoran profili</h2><div class="settings-logo"><div class="avatar" id="logo-preview">${p.logo?`<img src="${esc(p.logo)}" alt="Restoran logotipi">`:'R'}</div><div><label class="btn" for="logo-file">${icon('upload')}Logotip yuklash</label><input id="logo-file" type="file" accept="image/png,image/jpeg,image/webp" class="hidden-file"><p class="subtitle" style="margin-top:7px">PNG, JPG, WebP • 1 MB gacha</p></div></div><input type="hidden" name="logo" value="${esc(p.logo)}">${field('Restoran nomi','name',p.name,'text','required maxlength="80"')}${field('Manzil','address',p.address,'text','required maxlength="200"')}<div class="form-row">${field('Telefon','phone',p.phone,'tel','required pattern="[+0-9 ()-]{9,25}"')}${field('Elektron pochta','email',p.email,'email','required')}</div><div class="field"><label for="description">Restoran haqida</label><textarea id="description" name="description" maxlength="500">${esc(p.description)}</textarea></div></div><div><div class="panel"><h2>Buyurtma sozlamalari</h2><div class="form-row">${field('Tayyorlash vaqti (daq.)','prepTime',p.prepTime,'number','required min="5" max="180" step="1"')}${field('Demo komissiya (%)','commission',p.commission,'number','required min="0" max="50" step="0.1"')}</div><label class="check"><input name="sound" type="checkbox" ${p.sound?'checked':''}>Yangi buyurtma uchun ovozli signal</label><label class="check"><input name="notifications" type="checkbox" ${p.notifications?'checked':''}>Panel ichidagi bildirishnomalar</label>${btn('Ovozni tekshirish','test-sound','','small soft','volume')}<p class="subtitle" style="margin-top:14px">Ovoz brauzer bilan birinchi muloqotdan keyin ishlaydi.</p></div><div class="panel"><h2>Ma’lumotlar</h2><p class="subtitle">Panel ma’lumotlari faqat ushbu brauzerda saqlanadi. JSON nusxani yuklab olib, keyin qayta tiklashingiz mumkin.</p><div class="actions" style="margin-top:18px">${btn('Zaxira nusxa','backup','','small','download')}${btn('Tiklash','restore','','small','upload')}</div></div><div class="notice">Demo panel. Haqiqiy buyurtma, SMS, to‘lov, xodim kirishi va tarmoq orqali sinxronlash serverga ulanishni talab qiladi.</div><button class="btn primary" type="submit">${icon('check')}O‘zgarishlarni saqlash</button></div></div></form>`;}
function openModal(title,body,formId='',formData=''){
 modalReturn=document.activeElement;
 $('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Yopish">${icon('close')}</button></div>${formId?`<form id="${formId}" ${formData}>${body}<div class="form-error" role="alert" id="form-error"></div><div class="dialog-footer">${btn('Bekor qilish','close')}<button class="btn primary" type="submit">${icon('check')}Saqlash</button></div></form>`:body}`;
 $('#overlay').hidden=false;$('#dialog').focus();setTimeout(()=>$('#dialog input:not([type=hidden]),#dialog textarea')?.focus(),30);
}
function closeModal(){$('#overlay').hidden=true;$('#dialog').innerHTML='';modalReturn?.focus();}
function error(text){const el=$('#form-error');if(el)el.textContent=text;else toast(text);}
function productModal(id){const p=state.products.find(p=>p.id===id)||{name:'',description:'',category:state.categories[0]||'',price:'',emoji:'🍽️',image:'',available:true,modifiers:[]};openModal(id?'Mahsulotni tahrirlash':'Yangi mahsulot',`${field('Mahsulot nomi','name',p.name,'text','required maxlength="80"')}<div class="form-row"><div class="field"><label for="product-category">Kategoriya</label><select id="product-category" name="category" required>${state.categories.map(c=>`<option ${p.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>${field('Narxi (so‘m)','price',p.price,'number','required min="100" max="100000000" step="100"')}</div><div class="field"><label for="product-description">Tavsif</label><textarea id="product-description" name="description" maxlength="500">${esc(p.description)}</textarea></div><div class="form-row">${field('Rasmsiz belgi (emoji)','emoji',p.emoji,'text','maxlength="8"')}<div class="field"><label for="product-image">Mahsulot rasmi</label><input type="file" id="product-image" accept="image/png,image/jpeg,image/webp"><small>PNG/JPG/WebP, 1 MB gacha</small></div></div><input type="hidden" name="image" value="${esc(p.image)}"><div id="product-image-preview">${p.image?`<img class="logo-preview" src="${esc(p.image)}" alt="Mahsulot rasmi">`:''}</div><div class="field"><label for="modifiers">Modifikatorlar</label><textarea id="modifiers" name="modifiers" placeholder="Qo‘shimcha pishloq | 5000&#10;Achchiq sous | 2000">${esc(p.modifiers.map(m=>`${m.name} | ${m.price}`).join('\n'))}</textarea><small>Har qator: modifikator nomi | narxi (so‘m). Bepul variant: 0.</small></div><label class="check"><input type="checkbox" name="available" ${p.available?'checked':''}>Sotuvda mavjud</label>`,'product-form',`data-id="${esc(id||'')}"`);}
function categoryModal(){openModal('Kategoriyalar',`<div id="category-list">${state.categories.map(c=>`<div class="summary-line"><span>${esc(c)}</span><div class="actions">${btn('Nomlash','rename-category',c,'small','edit')}${btn('','delete-category',c,'small','trash')}</div></div>`).join('')}</div><form id="category-form">${field('Yangi kategoriya','name','','text','required maxlength="60"')}<button class="btn primary" type="submit">${icon('plus')}Qo‘shish</button><div id="form-error" class="form-error" role="alert"></div></form>`);}
function branchModal(id){const b=state.branches.find(b=>b.id===id)||{name:'',address:'',active:true};openModal(id?'Filialni tahrirlash':'Yangi filial',`${field('Filial nomi','name',b.name,'text','required maxlength="80"')}${field('Manzil','address',b.address,'text','required maxlength="200"')}<label class="check"><input type="checkbox" name="active" ${b.active?'checked':''}>Filial faol</label>`,'branch-form',`data-id="${esc(id||'')}"`);}
function promotionModal(id){const p=state.promos.find(p=>p.id===id)||{name:'',type:'discount',value:10,code:'',minOrder:0,ends:new Date(Date.now()+30*86400000).toISOString().slice(0,10),products:[],active:true};openModal(id?'Aksiyani tahrirlash':'Yangi aksiya',`${field('Aksiya nomi','name',p.name,'text','required maxlength="100"')}<div class="form-row"><div class="field"><label for="promo-type">Aksiya turi</label><select name="type" id="promo-type"><option value="discount" ${p.type==='discount'?'selected':''}>Chegirma (%)</option><option value="promo" ${p.type==='promo'?'selected':''}>Promokod (%)</option><option value="combo" ${p.type==='combo'?'selected':''}>Kombo (so‘m)</option></select></div>${field('Chegirma (%) / kombo narxi','value',p.value,'number','required min="1" max="100000000"')}</div>${field('Promokod (promokod turi uchun)','code',p.code,'text','maxlength="24" pattern="[A-Za-z0-9_-]*"')}<div class="form-row">${field('Minimal buyurtma (so‘m)','minOrder',p.minOrder,'number','required min="0" max="100000000"')}${field('Tugash sanasi','ends',p.ends,'date','required')}</div><div class="field"><label>Kombo mahsulotlari (kombo turi uchun)</label>${state.products.map(x=>`<label class="check" style="margin:4px 0"><input type="checkbox" name="products" value="${esc(x.id)}" ${p.products?.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</div><label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}>Aksiya faol</label>`,'promo-form',`data-id="${esc(id||'')}"`);}
function staffModal(id){const s=state.staff.find(s=>s.id===id)||{name:'',phone:'',role:'Operator',permissions:roles.Operator,active:true};if(s.role==='Ega')return;openModal(id?'Xodimni tahrirlash':'Yangi xodim',`${field('Ism va familiya','name',s.name,'text','required maxlength="80"')}${field('Telefon raqami','phone',s.phone,'tel','required pattern="[+0-9 ()-]{9,25}"')}<div class="field"><label for="staff-role">Rol</label><select id="staff-role" name="role">${Object.keys(roles).filter(r=>r!=='Ega').map(r=>`<option ${r===s.role?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Bo‘lim ruxsatlari</label><div class="permissions">${navItems.map(([key,label])=>`<label class="check"><input type="checkbox" name="permissions" value="${key}" ${s.permissions.includes(key)?'checked':''}>${label}</label>`).join('')}</div></div><label class="check"><input type="checkbox" name="active" ${s.active?'checked':''}>Xodim faol</label><div class="notice">Saqlash SMS yoki taklif yubormaydi. Ruxsatlar server ulangandan keyin foydalanuvchi kirishida qo‘llanadi.</div>`,'staff-form',`data-id="${esc(id||'')}"`);}
function acceptModal(id){const o=state.orders.find(o=>o.id===id);if(o?.status!=='new')return;openModal(`#${esc(id)} — Qabul qilish`,`<p class="subtitle">${esc(o.customer)} • ${money(total(o))} so‘m</p><div style="margin-top:20px">${field('Tayyorlash vaqti (daqiqa)','minutes',state.profile.prepTime,'number','required min="5" max="180"')}</div>`,'accept-form',`data-id="${esc(id)}"`);}
function rejectModal(id){const o=state.orders.find(o=>o.id===id);if(o?.status!=='new')return;openModal(`#${esc(id)} — Rad etish`,`<div class="field"><label for="reason">Rad etish sababi</label><select id="reason" name="reason"><option>Mahsulot qolmagan</option><option>Oshxona band</option><option>Filial yopiq</option><option>Boshqa sabab</option></select></div><div class="field"><label for="reason-note">Izoh</label><textarea id="reason-note" name="note" maxlength="300"></textarea></div>`,'reject-form',`data-id="${esc(id)}"`);}
function confirmAction(title,text,action,id){openModal(title,`<p class="subtitle">${esc(text)}</p><div class="dialog-footer">${btn('Bekor qilish','close')}${btn('Tasdiqlash',action,id,'danger')}</div>`);}
function transition(id,from,to,extra={}){const o=state.orders.find(o=>o.id===id);if(!o||o.status!==from){toast('Buyurtma holati allaqachon o‘zgargan.');return false;}return update(s=>Object.assign(s.orders.find(o=>o.id===id),{status:to,...extra}));}
function beep(force=false){if(!state.profile.sound&&!force)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume().then(()=>{[0,.2].forEach((delay,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.frequency.value=i?880:660;g.gain.setValueAtTime(.0001,audioContext.currentTime+delay);g.gain.exponentialRampToValueAtTime(.12,audioContext.currentTime+delay+.02);g.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+delay+.18);o.start(audioContext.currentTime+delay);o.stop(audioContext.currentTime+delay+.2);});}).catch(()=>toast('Brauzer ovozni blokladi. Sozlamalarni tekshiring.'));}catch{toast('Bu brauzerda ovozli signal ishlamaydi.');}}
function demoOrder(){if(state.busy){toast('Restoran band rejimida. Avval qabul qilishni yoqing.');return;}const branches=state.branches.filter(b=>b.active&&(state.selectedBranch==='all'||b.id===state.selectedBranch)),products=state.products.filter(p=>p.available);if(!branches.length||!products.length){toast('Faol filial va sotuvdagi mahsulot kerak.');return;}const p=products[Math.floor(Math.random()*products.length)],id=String(Math.max(1048,...state.orders.map(o=>Number(o.id)||0))+1);if(update(s=>s.orders.unshift({id,customer:'Demo mijoz',phone:'+998 90 000 00 00',items:[{name:p.name,qty:1,price:p.price}],status:'new',created:Date.now(),branch:branches[0].id,payment:'Karta',note:'Sinov uchun yaratilgan buyurtma'}))){beep();if(state.profile.notifications)toast(`Yangi demo buyurtma: #${id}`);orderTab='active';render();}}
function printReceipt(id){const o=state.orders.find(o=>o.id===id);if(!o)return;$('.receipt')?.remove();const el=document.createElement('article');el.className='receipt';el.innerHTML=`<h2>${esc(state.profile.name)}</h2><p>DEMO CHEK • FISKAL EMAS</p><p>${esc(state.profile.address)}<br>${esc(state.profile.phone)}</p><hr><p>Buyurtma #${esc(o.id)}<br>${new Date(o.created).toLocaleString('uz-UZ')}<br>${esc(o.customer)}</p><table>${o.items.map(i=>`<tr><td>${esc(i.name)} × ${i.qty}</td><td>${money(i.price*i.qty)}</td></tr>`).join('')}</table><hr><p><b>JAMI: ${money(total(o))} so‘m</b><br>${esc(o.payment)}</p>${o.note?`<p>${esc(o.note)}</p>`:''}<p>Xaridingiz uchun rahmat!</p>`;document.body.append(el);window.print();}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[\t\r\n ]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(';')).join('\r\n');}
function exportFinance(){const list=orders().filter(o=>o.status==='completed'&&(financePeriod==='all'||new Date(o.completed||o.created).toDateString()===new Date().toDateString()));download('teztaom-savdo.csv',csv([['Buyurtma','Sana','Savdo (so‘m)','Komissiya (so‘m)','Sof tushum (so‘m)','To‘lov'],...list.map(o=>[o.id,new Date(o.completed||o.created).toLocaleString('uz-UZ'),total(o),Math.round(total(o)*state.profile.commission/100),total(o)-Math.round(total(o)*state.profile.commission/100),o.payment])]),'text/csv;charset=utf-8');toast('Hisobot yuklab olindi.');}
function readImage(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('PNG, JPG yoki WebP rasm tanlang.'));if(file.size>1024*1024)return reject(new Error('Rasm hajmi 1 MB dan kichik bo‘lsin.'));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Rasmni o‘qib bo‘lmadi.'));r.readAsDataURL(file);});}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;const delimiter=(text.split(/\r?\n/)[0].match(/;/g)||[]).length>(text.split(/\r?\n/)[0].match(/,/g)||[]).length?';':',';for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw new Error('CSV faylida yopilmagan qo‘shtirnoq bor.');row.push(field);if(row.some(v=>v.trim()))rows.push(row);return rows;}
async function parseXLSX(file){
 const buf=await file.arrayBuffer(),data=new DataView(buf),bytes=new Uint8Array(buf),decoder=new TextDecoder();let end=-1;
 for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(data.getUint32(i,true)===0x06054b50){end=i;break;}
 if(end<0)throw new Error('XLSX fayli buzilgan. CSV formatini sinab ko‘ring.');
 const entries={},count=data.getUint16(end+10,true);let pos=data.getUint32(end+16,true),unpacked=0;
 if(count>2000)throw new Error('Excel faylida juda ko‘p varaqlar bor.');
 for(let i=0;i<count;i++){if(data.getUint32(pos,true)!==0x02014b50)throw new Error('XLSX tuzilmasi noto‘g‘ri.');const size=data.getUint32(pos+20,true),uncompressed=data.getUint32(pos+24,true),method=data.getUint16(pos+10,true),len=data.getUint16(pos+28,true),extra=data.getUint16(pos+30,true),comment=data.getUint16(pos+32,true),offset=data.getUint32(pos+42,true),name=decoder.decode(bytes.slice(pos+46,pos+46+len));unpacked+=uncompressed;if(unpacked>20*1024*1024)throw new Error('Excel fayli ochilganda juda katta. CSV ishlating.');entries[name]={size,method,offset};pos+=46+len+extra+comment;}
 async function entry(name){const e=entries[name];if(!e)return '';const start=e.offset+30+data.getUint16(e.offset+26,true)+data.getUint16(e.offset+28,true),b=bytes.slice(start,start+e.size);if(e.method===0)return decoder.decode(b);if(e.method!==8)throw new Error('Excel siqish usuli qo‘llanmaydi. CSV ishlating.');try{return await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).text();}catch{throw new Error('Bu brauzer XLSX ocholmaydi. Excel’dan CSV qilib saqlang.');}}
 const xml=s=>new DOMParser().parseFromString(s,'application/xml');
 const strings=xml(await entry('xl/sharedStrings.xml'));const shared=[...strings.getElementsByTagName('si')].map(n=>[...n.getElementsByTagName('t')].map(t=>t.textContent).join(''));
 const workbook=xml(await entry('xl/workbook.xml'));const first=workbook.getElementsByTagName('sheet')[0];let target='xl/worksheets/sheet1.xml';
 if(first){const rels=xml(await entry('xl/_rels/workbook.xml.rels'));const rel=[...rels.getElementsByTagName('Relationship')].find(r=>r.getAttribute('Id')===first.getAttribute('r:id'));if(rel){const t=rel.getAttribute('Target');target=t.startsWith('/')?t.slice(1):'xl/'+t.replace(/^\.\//,'');}}
 const source=await entry(target);if(!source)throw new Error('Birinchi varaq topilmadi.');const sheet=xml(source),rows=[];
 for(const row of sheet.getElementsByTagName('row')){const values=[];for(const c of row.getElementsByTagName('c')){const ref=c.getAttribute('r')||'A1',letters=ref.match(/[A-Z]+/)?.[0]||'A';let col=0;for(const char of letters)col=col*26+char.charCodeAt(0)-64;if(col>100)continue;const type=c.getAttribute('t'),v=c.getElementsByTagName('v')[0]?.textContent||'';values[col-1]=type==='s'?(shared[Number(v)]||''):type==='inlineStr'?[...c.getElementsByTagName('t')].map(t=>t.textContent).join(''):v;}if(values.some(v=>String(v).trim()))rows.push(values);if(rows.length>2001)throw new Error('Bir martada ko‘pi bilan 2000 mahsulot import qiling.');}
 return rows;
}
function importModal(){openModal('Excel orqali menyu importi',`<div class="notice">.xlsx va Excel CSV fayllari qo‘llanadi. Birinchi varaq, birinchi qatorda ustun nomlari bo‘lsin. 2000 mahsulot / 2 MB gacha.</div><p class="subtitle">Ustunlar: <b>nomi, kategoriya, narx, tavsif, mavjud</b>. Narx faqat son bilan. Mavjud: 1 yoki 0. Yangi mahsulotlar qo‘shiladi; mavjudlari o‘zgarmaydi.</p><div class="actions" style="margin:18px 0">${btn('CSV shablonni yuklash','import-template','','soft','download')}</div><div class="field"><label for="import-file">Excel / CSV fayli</label><input id="import-file" type="file" accept=".xlsx,.csv,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></div><div id="import-preview"></div><div id="form-error" class="form-error" role="alert"></div>`);}
let pendingImport=[];
async function previewImport(file){pendingImport=[];if(!file)return;if(file.size>2*1024*1024){error('Fayl 2 MB dan kichik bo‘lsin.');return;}$('#import-preview').textContent='Fayl tekshirilmoqda…';try{const rows=/\.xlsx$/i.test(file.name)?await parseXLSX(file):/\.csv$/i.test(file.name)?parseCSV((await file.text()).replace(/^\uFEFF/,'')):(()=>{throw new Error('Faqat .xlsx yoki .csv fayl tanlang.');})();if(rows.length<2)throw new Error('Faylda sarlavha va kamida bir mahsulot bo‘lsin.');if(rows.length>2001)throw new Error('2000 mahsulotdan ko‘p import qilib bo‘lmaydi.');const head=rows[0].map(x=>String(x).trim().toLowerCase()),index=(...names)=>head.findIndex(x=>names.includes(x)),ni=index('nomi','name','mahsulot'),ci=index('kategoriya','category'),pi=index('narx','price'),di=index('tavsif','description'),ai=index('mavjud','available');if([ni,ci,pi].some(i=>i<0))throw new Error('nomi, kategoriya, narx ustunlari majburiy.');const items=rows.slice(1).map((r,i)=>{const name=String(r[ni]||'').trim(),category=String(r[ci]||'').trim(),price=Number(String(r[pi]||'').replace(/\s/g,''));if(!name||name.length>80||!category||category.length>60||!Number.isFinite(price)||price<100||price>100000000)throw new Error(`${i+2}-qatorda nom, kategoriya yoki narx noto‘g‘ri.`);return {id:uid(),name,category,price,description:String(r[di]||'').slice(0,500),available:ai<0||!['0','false','yo‘q','yoq'].includes(String(r[ai]).trim().toLowerCase()),emoji:'🍽️',image:'',modifiers:[]};});pendingImport=items;$('#import-preview').innerHTML=`<span class="tag success">${items.length} ta mahsulot tayyor</span><div class="table-wrap" style="margin:15px 0"><table><thead><tr><th>NOMI</th><th>NARX</th></tr></thead><tbody>${items.slice(0,5).map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.price)}</td></tr>`).join('')}</tbody></table></div>${btn(`${items.length} mahsulotni qo‘shish`,'import-confirm','','primary','check')}`;error('');}catch(e){$('#import-preview').innerHTML='';error(e.message);}}
function backupValid(s){return s?.version===1&&Array.isArray(s.products)&&s.products.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&typeof p.category==='string'&&typeof p.description==='string'&&Number.isFinite(p.price)&&p.price>=0&&Array.isArray(p.modifiers)&&p.modifiers.every(m=>typeof m.name==='string'&&Number.isFinite(m.price))&&typeof p.available==='boolean'&&(!p.image||/^data:image\/(png|jpeg|webp);base64,/.test(p.image)))&&Array.isArray(s.categories)&&s.categories.every(c=>typeof c==='string')&&s.profile&&typeof s.profile.name==='string'&&typeof s.profile.phone==='string'&&typeof s.profile.address==='string'&&typeof s.profile.email==='string'&&typeof s.profile.description==='string'&&Number.isFinite(s.profile.commission)&&s.profile.commission>=0&&s.profile.commission<=50&&Number.isFinite(s.profile.prepTime)&&s.profile.prepTime>=5&&s.profile.prepTime<=180&&(!s.profile.logo||s.profile.logo==='assets/lazzat-logo.png'||/^data:image\/(png|jpeg|webp);base64,/.test(s.profile.logo))&&Array.isArray(s.orders)&&s.orders.every(o=>typeof o.id==='string'&&typeof o.customer==='string'&&typeof o.payment==='string'&&['new','preparing','ready','completed','rejected'].includes(o.status)&&Number.isFinite(o.created)&&Array.isArray(o.items)&&o.items.every(i=>typeof i.name==='string'&&Number.isFinite(i.price)&&i.price>=0&&Number.isInteger(i.qty)&&i.qty>0))&&Array.isArray(s.branches)&&s.branches.length>0&&s.branches.every(b=>typeof b.id==='string'&&typeof b.name==='string'&&typeof b.address==='string'&&Array.isArray(b.schedule)&&b.schedule.length===7&&b.schedule.every(d=>typeof d.name==='string'&&/^\d{2}:\d{2}$/.test(d.from)&&/^\d{2}:\d{2}$/.test(d.to)))&&Array.isArray(s.promos)&&s.promos.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&['discount','promo','combo'].includes(p.type)&&Number.isFinite(p.value)&&Number.isFinite(p.minOrder)&&typeof p.ends==='string'&&Array.isArray(p.products)&&p.products.every(id=>typeof id==='string'))&&Array.isArray(s.reviews)&&s.reviews.every(r=>typeof r.id==='string'&&typeof r.name==='string'&&typeof r.text==='string'&&typeof r.reply==='string'&&Number.isInteger(r.rating)&&r.rating>=1&&r.rating<=5)&&Array.isArray(s.staff)&&s.staff.every(x=>typeof x.id==='string'&&typeof x.name==='string'&&typeof x.phone==='string'&&Object.hasOwn(roles,x.role)&&Array.isArray(x.permissions)&&x.permissions.every(id=>navItems.some(n=>n[0]===id)))&&s.staff.some(x=>x.role==='Ega'&&x.active)&&Array.isArray(s.payouts)&&s.payouts.every(p=>typeof p.date==='string'&&Number.isFinite(p.amount));}
function restoreModal(){openModal('Zaxira nusxadan tiklash',`<div class="notice">Tiklash hozirgi ma’lumotlarni tanlangan nusxa bilan almashtiradi. Avval joriy zaxira nusxani yuklab oling.</div><div class="actions">${btn('Joriy nusxani yuklash','backup','','soft','download')}</div><form id="restore-form"><div class="field" style="margin-top:20px"><label for="restore-file">Lazzat JSON nusxasi</label><input id="restore-file" type="file" accept=".json,application/json" required></div><label class="check"><input type="checkbox" required>Joriy ma’lumotlarni almashtirishga roziman</label><div id="form-error" class="form-error" role="alert"></div><div class="dialog-footer">${btn('Bekor qilish','close')}<button type="submit" class="btn danger">Tiklash</button></div></form>`);}
const actions={
 nav:id=>{page=id;search='';render();window.scrollTo({top:0});},'order-tab':id=>{orderTab=id;render();},'menu-tab':id=>{menuTab=id;render();},close:closeModal,
 busy:()=>{if(update(s=>s.busy=!s.busy)){render();toast(state.busy?'Band rejimi yoqildi.':'Buyurtma qabul qilish yoqildi.');}},
 notifications:()=>openModal('Bildirishnomalar',`<p class="subtitle">${state.profile.notifications?'Bildirishnomalar yoqilgan.':'Bildirishnomalar sozlamalarda o‘chirilgan.'}</p>${orders().filter(o=>o.status==='new').map(o=>`<div class="summary-line"><span>Yangi buyurtma <strong>#${esc(o.id)}</strong></span><strong>${money(total(o))} so‘m</strong></div>`).join('')||empty('Yangi bildirishnomalar yo‘q')}`),
 help:()=>openModal('Panel bo‘yicha qo‘llanma',`<div class="order-preview"><p><b>1. Buyurtmalar:</b> “Demo buyurtma” bilan sinab ko‘ring. Qabul qilib vaqt belgilang, tayyor bo‘lgach “Tayyor”, keyin “Kuryerga berildi”ni bosing. Printer belgisi demo chekni chiqaradi.</p><p><b>2. Menyu:</b> mahsulot, kategoriya, narx, rasm va modifikatorlarni tahrirlang. “Sotuvda” tugmasi mahsulotni stop-listga o‘tkazadi. Excel XLSX yoki CSV faylidan import qiling.</p><p><b>3. Ish vaqti:</b> filiallar jadvalini saqlang va kerak bo‘lsa band rejimini yoqing.</p><p><b>4. Moliya va analitika:</b> yakunlangan demo buyurtmalar asosida yangilanadi. Hisobot CSV shaklida yuklanadi.</p><p><b>5. Ma’lumotlar:</b> brauzer xotirasida. Sozlamalardan zaxira nusxa oling. Boshqa qurilmalar bilan sinxronlash va haqiqiy rollar server integratsiyasini talab qiladi.</p></div>`),
 'demo-order':demoOrder,accept:acceptModal,reject:rejectModal,print:printReceipt,
 ready:id=>{if(transition(id,'preparing','ready',{readyAt:Date.now()})){render();toast(`#${id} tayyor deb belgilandi.`);}},
 complete:id=>{if(transition(id,'ready','completed',{completed:Date.now()})){render();toast(`#${id} kuryerga berildi va demo savdoga qo‘shildi.`);}},
 product:productModal,categories:categoryModal,branch:branchModal,promotion:promotionModal,staff:staffModal,
 availability:id=>{if(update(s=>{const p=s.products.find(p=>p.id===id);if(p)p.available=!p.available;}))render();},
 'delete-product':id=>confirmAction('Mahsulotni o‘chirish','Mahsulot menyudan o‘chiriladi. Eski buyurtmalardagi ma’lumotlar saqlanadi.','confirm-delete-product',id),
 'confirm-delete-product':id=>{if(update(s=>{s.products=s.products.filter(p=>p.id!==id);s.promos.forEach(p=>{p.products=p.products.filter(x=>x!==id);if(p.type==='combo'&&p.products.length<2)p.active=false;});})){closeModal();render();toast('Mahsulot o‘chirildi.');}},
 'rename-category':id=>openModal('Kategoriyani nomlash',field('Yangi nom','name',id,'text','required maxlength="60"'),'rename-category-form',`data-id="${esc(id)}"`),
 'delete-category':id=>{if(state.products.some(p=>p.category===id)){toast('Avval bu kategoriyadagi mahsulotlarni boshqa kategoriyaga o‘tkazing.');return;}if(state.categories.length<=1){toast('Kamida bitta kategoriya qolishi kerak.');return;}if(update(s=>s.categories=s.categories.filter(c=>c!==id))){if(menuTab===id)menuTab='all';categoryModal();render();}},
 'branch-active':id=>{if(update(s=>{const b=s.branches.find(b=>b.id===id);b.active=!b.active;}))render();},
 'promo-active':id=>{const p=state.promos.find(p=>p.id===id);if(!p.active&&p.type==='combo'&&p.products.length<2){toast('Kombo uchun kamida 2 mahsulot tanlang.');return;}if(update(s=>{const p=s.promos.find(p=>p.id===id);p.active=!p.active;}))render();},
 'delete-promo':id=>confirmAction('Aksiyani o‘chirish','Aksiya ma’lumotlari o‘chiriladi.','confirm-delete-promo',id),
 'confirm-delete-promo':id=>{if(update(s=>s.promos=s.promos.filter(p=>p.id!==id))){closeModal();render();}},
 'staff-active':id=>{if(update(s=>{const staff=s.staff.find(x=>x.id===id);if(staff.role!=='Ega')staff.active=!staff.active;}))render();},
 reply:id=>{const r=state.reviews.find(r=>r.id===id);openModal('Mijozga javob',`<p class="subtitle">${esc(r.name)}: ${esc(r.text)}</p><div class="field" style="margin-top:20px"><label for="reply-text">Javob matni</label><textarea id="reply-text" name="reply" required maxlength="1000">${esc(r.reply)}</textarea></div>`,'reply-form',`data-id="${esc(id)}"`);},
 'report-review':id=>openModal('Sharh bo‘yicha shikoyat',`<div class="field"><label for="report-reason">Sabab</label><select id="report-reason" name="reason"><option>Noto‘g‘ri ma’lumot</option><option>Haqoratli mazmun</option><option>Spam yoki reklama</option></select></div><p class="subtitle">Hozircha belgi shu brauzerda saqlanadi; moderatorga yuborilmaydi.</p>`,'report-form',`data-id="${esc(id)}"`),
 'test-sound':()=>beep(true),'export-finance':exportFinance,import:importModal,
 'import-template':()=>download('menyu-shablon.csv',csv([['nomi','kategoriya','narx','tavsif','mavjud'],['Tovuq shashlik','Milliy taomlar',25000,'150 g',1]]),'text/csv;charset=utf-8'),
 'import-confirm':()=>{if(!pendingImport.length)return;if(update(s=>{s.products.push(...pendingImport);s.categories=[...new Set([...s.categories,...pendingImport.map(p=>p.category)])];})){const n=pendingImport.length;pendingImport=[];closeModal();menuTab='all';render();toast(`${n} ta mahsulot qo‘shildi.`);}},
 backup:()=>{download('teztaom-zaxira-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');toast('Zaxira nusxa yuklab olindi.');},restore:restoreModal
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action;actions[a]?.(el.dataset.id);});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeModal();});
document.addEventListener('keydown',e=>{if($('#overlay').hidden)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const list=$$('button:not(:disabled),input:not([type=hidden]),select,textarea,a[href]',$('#dialog')).filter(x=>x.offsetParent!==null);if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#dialog'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;const start=e.target.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(start,start);}});
document.addEventListener('change',async e=>{const id=e.target.id;try{
 if(['branch-filter','schedule-branch'].includes(id)){if(update(s=>s.selectedBranch=e.target.value))render();}
 if(id==='finance-period'){financePeriod=e.target.value;render();}if(id==='analytics-period'){analyticsPeriod=Number(e.target.value);render();}if(id==='review-filter'){reviewFilter=e.target.value;render();}
 if(id==='staff-role'){$$('input[name=permissions]',$('#staff-form')).forEach(x=>x.checked=roles[e.target.value].includes(x.value));}
 if(id==='logo-file'||id==='product-image'){const result=await readImage(e.target.files[0]);if(!result)return;const form=id==='logo-file'?$('#settings-form'):$('#product-form');form.elements[id==='logo-file'?'logo':'image'].value=result;const preview=id==='logo-file'?$('#logo-preview'):$('#product-image-preview');preview.innerHTML=`<img class="logo-preview" src="${result}" alt="Yuklangan rasm">`;}
 if(id==='import-file')await previewImport(e.target.files[0]);
 }catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(!form.checkValidity()){form.reportValidity();return;}const f=new FormData(form),value=n=>String(f.get(n)||'').trim(),id=form.dataset.id;let ok=false;
 try{switch(form.id){
 case 'product-form':{const modifiers=value('modifiers').split('\n').filter(l=>l.trim()).map(l=>{const parts=l.split('|'),name=parts[0]?.trim(),raw=parts[1]?.trim(),price=Number(raw);if(parts.length!==2||!name||!raw||!Number.isFinite(price)||price<0||price>100000000)throw new Error('Modifikator formati: Nomi | 5000. Narx manfiy bo‘lmasin.');return {name,price};});if(!value('name'))throw new Error('Mahsulot nomini yozing.');const p={id:id||uid(),name:value('name'),category:value('category'),price:Number(value('price')),description:value('description'),emoji:value('emoji')||'🍽️',image:value('image'),available:f.has('available'),modifiers};ok=update(s=>{const i=s.products.findIndex(x=>x.id===id);if(i>=0)s.products[i]=p;else s.products.push(p);});break;}
 case 'category-form':{const name=value('name');if(!name)throw new Error('Kategoriya nomini yozing.');if(state.categories.some(c=>c.toLowerCase()===name.toLowerCase()))throw new Error('Bu kategoriya mavjud.');if(update(s=>s.categories.push(name))){render();categoryModal();toast('Kategoriya qo‘shildi.');}return;}
 case 'rename-category-form':{const name=value('name');if(!name)throw new Error('Kategoriya nomini yozing.');if(state.categories.some(c=>c!==id&&c.toLowerCase()===name.toLowerCase()))throw new Error('Bu nomdagi kategoriya mavjud.');ok=update(s=>{s.categories=s.categories.map(c=>c===id?name:c);s.products.forEach(p=>{if(p.category===id)p.category=name;});});if(menuTab===id)menuTab=name;break;}
 case 'branch-form':{if(!value('name')||!value('address'))throw new Error('Filial nomi va manzilini to‘ldiring.');ok=update(s=>{const b=s.branches.find(b=>b.id===id);if(b)Object.assign(b,{name:value('name'),address:value('address'),active:f.has('active')});else s.branches.push({id:uid(),name:value('name'),address:value('address'),active:f.has('active'),schedule:dayNames.map(name=>({name,open:true,from:'09:00',to:'23:00'}))});});break;}
 case 'schedule-form':{const schedule=dayNames.map((name,i)=>({name,open:f.has('open'+i),from:value('from'+i),to:value('to'+i)}));if(schedule.some(d=>d.open&&d.from===d.to))throw new Error('Ochilish va yopilish vaqti bir xil bo‘lmasin.');if(update(s=>s.branches.find(b=>b.id===id).schedule=schedule)){render();toast('Ish jadvali saqlandi.');}return;}
 case 'promo-form':{const type=value('type'),amount=Number(value('value')),products=f.getAll('products'),code=value('code').toUpperCase();if(!value('name'))throw new Error('Aksiya nomini yozing.');if(type!=='combo'&&amount>100)throw new Error('Chegirma 100% dan oshmasin.');if(type==='promo'&&!code)throw new Error('Promokodni yozing.');if(code&&state.promos.some(p=>p.id!==id&&p.code===code))throw new Error('Bu promokod mavjud.');if(type==='combo'&&products.length<2)throw new Error('Kombo uchun kamida 2 ta mahsulot tanlang.');const p={id:id||uid(),name:value('name'),type,value:amount,code,minOrder:Number(value('minOrder')),ends:value('ends'),products,active:f.has('active')};ok=update(s=>{const i=s.promos.findIndex(p=>p.id===id);if(i>=0)s.promos[i]=p;else s.promos.push(p);});break;}
 case 'staff-form':{if(!value('name'))throw new Error('Xodim ismini yozing.');const phone=value('phone'),clean=x=>x.replace(/\D/g,'');if(state.staff.some(s=>s.id!==id&&clean(s.phone)===clean(phone)))throw new Error('Bu telefon raqamli xodim mavjud.');const permissions=f.getAll('permissions');if(!permissions.length)throw new Error('Kamida bitta bo‘lim ruxsatini tanlang.');const x={id:id||uid(),name:value('name'),phone,role:value('role'),permissions,active:f.has('active')};ok=update(s=>{const i=s.staff.findIndex(x=>x.id===id);if(i>=0&&s.staff[i].role!=='Ega')s.staff[i]=x;else if(i<0)s.staff.push(x);});break;}
 case 'accept-form':ok=transition(id,'new','preparing',{accepted:Date.now(),prepTime:Number(value('minutes'))});break;
 case 'reject-form':ok=transition(id,'new','rejected',{rejected:Date.now(),reason:value('reason'),rejectionNote:value('note')});break;
 case 'reply-form':if(!value('reply'))throw new Error('Javob matnini yozing.');ok=update(s=>s.reviews.find(r=>r.id===id).reply=value('reply'));break;
 case 'report-form':ok=update(s=>Object.assign(s.reviews.find(r=>r.id===id),{reported:true,reportReason:value('reason')}));break;
 case 'settings-form':{if(!value('name')||!value('address'))throw new Error('Restoran nomi va manzilini to‘ldiring.');if(update(s=>s.profile={...s.profile,name:value('name'),phone:value('phone'),email:value('email'),address:value('address'),description:value('description'),logo:value('logo'),prepTime:Number(value('prepTime')),commission:Number(value('commission')),sound:f.has('sound'),notifications:f.has('notifications')})){render();toast('Sozlamalar saqlandi.');}return;}
 case 'restore-form':{const file=$('#restore-file').files[0];if(!file||file.size>12*1024*1024)throw new Error('JSON faylni tanlang (12 MB gacha).');let restored;try{restored=JSON.parse(await file.text());}catch{throw new Error('JSON faylni o‘qib bo‘lmadi.');}if(!backupValid(restored))throw new Error('Nusxa formati noto‘g‘ri yoki Lazzat paneliga mos emas.');restored.selectedBranch='all';ok=commit(restored);break;}
 default:return;
 }if(ok){closeModal();render();toast('O‘zgarishlar saqlandi.');}
 }catch(e){error(e.message);}
});
window.addEventListener('storage',e=>{if(e.key==='teztaom-seller-v1'){if(!$('#overlay').hidden||$('#settings-form')||$('#schedule-form')){toast('Boshqa oynada ma’lumotlar o‘zgardi. Yangilashdan oldin ochiq formani tugating.');return;}state=load();render();}});
render();
if(storageWarning)toast('Brauzer xotirasi ishlamayapti. O‘zgarishlar saqlanmasligi mumkin.');
setInterval(()=>{if(page==='orders'&&$('#overlay').hidden&&document.activeElement?.id!=='search')render();},60000);
